const $=s=>document.querySelector(s), app=$('#app');
const closeModal=()=>$('#modal [data-close]')?.click();
const formValues=form=>Object.fromEntries([...new FormData(form)].filter(([,value])=>typeof value==='string'));
const storage={get:key=>{try{return localStorage.getItem(key)}catch{return null}},set:(key,value)=>{try{localStorage.setItem(key,value)}catch{}},remove:key=>{try{localStorage.removeItem(key)}catch{}}};
const urlState=new URLSearchParams(location.search);if(urlState.get('manage-consent')==='1')storage.remove('ndivepa-analytics-consent');let savedFavorites=[];try{const parsed=JSON.parse(storage.get('ndivepa-favorites')||'[]');if(Array.isArray(parsed))savedFavorites=parsed.filter(id=>typeof id==='string').slice(0,500)}catch{storage.remove('ndivepa-favorites')}
const state={auth:null,csrfToken:null,section:'store',data:{},visitor:storage.get('ndivepa-visitor')||globalThis.crypto?.randomUUID?.()||`visitor_${Date.now().toString(36)}`,query:(urlState.get('q')||'').slice(0,120),category:'all',sort:'featured',analyticsDays:'30',analyticsConsent:storage.get('ndivepa-analytics-consent'),favorites:new Set(savedFavorites),opportunities:[],opportunityPrograms:[],blockedPrograms:[],opportunityMeta:null,discoveryGeo:'PY'};storage.set('ndivepa-visitor',state.visitor);
const api=async(path,options={})=>{const method=(options.method||'GET').toUpperCase(),headers=new Headers(options.headers||{});if(options.body&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');if(['POST','PUT','PATCH','DELETE'].includes(method)&&state.csrfToken)headers.set('X-Ndivepa-Csrf',state.csrfToken);let response;try{response=await fetch(`/api${path}`,{credentials:'same-origin',...options,method,headers,signal:options.signal||(globalThis.AbortSignal?.timeout?AbortSignal.timeout(15000):undefined)})}catch(error){throw Error(error.name==='TimeoutError'||error.name==='AbortError'?'La solicitud tardó demasiado. Intenta nuevamente.':'No se pudo conectar con Ndivepa.')}const text=response.status===204?'':await response.text(),type=response.headers.get('content-type')||'';let data={};if(text){if(type.includes('json')){try{data=JSON.parse(text)}catch{throw Error('Ndivepa devolvió una respuesta JSON incompleta.')}}else data={message:text}}if(!response.ok){if(response.status===401&&path!=='/auth/me'){state.auth=null;state.csrfToken=null}throw Error(data?.error?.message||data?.error||data?.message||`No se pudo completar la operación (${response.status}).`)}return data};
const esc=(x='')=>String(x).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=(n,c='USD')=>{if(n===null||n===undefined)return'Consultar precio';try{return new Intl.NumberFormat('es-PY',{style:'currency',currency:String(c||'USD').toUpperCase()}).format(Number(n))}catch{return `${Number(n).toFixed(2)} ${esc(c)}`}};
const status=x=>`<span class="badge ${['valid','active','healthy','approved','paid','published','confirmed'].includes(x)?'good':x==='invalid'||x==='down'||x==='rejected'?'danger':'warn'}">${esc(x)}</span>`;
let toastTimer;const toast=m=>{const t=$('#toast');t.textContent=String(m||'');t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)};
const media=(value,alt='')=>{const source=String(value||'🔗');return /^\/uploads\/[A-Za-z0-9/_-]+\.(?:png|jpe?g|webp|avif|gif)$/i.test(source)?`<img src="${esc(source)}" alt="${esc(alt)}" loading="lazy" decoding="async">`:`<span aria-hidden="true">${esc(source)}</span>`};
async function load(){const session=await api('/auth/me');state.auth=session.user;state.csrfToken=session.csrfToken||null;if(!state.auth){[state.data.products,state.data.settings]=await Promise.all([api('/products'),api('/store-config')]);return}const calls=['admin/products','admin/categories','admin/merchants','admin/networks','admin/programs','admin/campaigns','admin/links','admin/conversions','admin/commissions','admin/alerts','admin/audits','admin/events','affiliate-summary','store-config'];const values=await Promise.all(calls.map(x=>api(`/${x}`)));[state.data.products,state.data.categories,state.data.merchants,state.data.networks,state.data.programs,state.data.campaigns,state.data.links,state.data.conversions,state.data.commissions,state.data.alerts,state.data.audits,state.data.events,state.data.summary,state.data.settings]=values}
const nav=[['dashboard','Dashboard'],['products','Productos'],['discovery','Descubrimiento'],['merchants','Comercios'],['programs','Programas'],['campaigns','Campañas'],['conversions','Conversiones'],['commissions','Comisiones'],['links','Enlaces'],['analytics','Analítica'],['alerts','Alertas'],['settings','Seguridad'],['store','Ver sitio']];
function layout(content){return `<div class="shell"><aside class="side"><div class="brand">Ndi<em>vepa</em></div><small>AFILIADOS</small><nav class="nav" aria-label="Administración">${nav.map(([id,label])=>`<button data-section="${id}" class="${state.section===id?'active':''}" ${state.section===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="side-foot"><strong>${esc(state.auth.name)}</strong>Administrador<br><button class="icon-btn" data-action="logout">Cerrar sesión</button></div></aside><main class="view" id="main-content" tabindex="-1">${content}</main></div>`}const header=(t,d,a='')=>`<div class="top"><div><h1>${esc(t)}</h1><p>${esc(d)}</p></div>${a}</div>`;
function dashboard(){const s=state.data.summary;return layout(`${header('Inteligencia de afiliación','Visitas, clics, conversiones y comisiones; las ventas atribuidas no son ingresos propios.','<button class="btn" data-action="new-product">+ Agregar producto</button>')}<section class="stats"><article class="stat"><span>Usuarios activos</span><strong>${s.activeUsers}</strong></article><article class="stat"><span>Sesiones</span><strong>${s.sessions}</strong></article><article class="stat"><span>Vistas de producto</span><strong>${s.productViews}</strong></article><article class="stat"><span>Clics afiliados</span><strong>${s.affiliateClicks}</strong></article><article class="stat"><span>Conversiones</span><strong>${s.conversions}</strong></article><article class="stat"><span>CTR</span><strong>${s.ctr}%</strong></article><article class="stat"><span>Comisión pendiente</span><strong>${money(s.commissionPending)}</strong></article><article class="stat"><span>Comisión aprobada</span><strong>${money(s.commissionApproved)}</strong></article><article class="stat"><span>Comisión pagada</span><strong>${money(s.commissionPaid)}</strong></article><article class="stat"><span>EPC</span><strong>${money(s.epc)}</strong></article></section><section class="grid"><article class="panel"><h2>Embudo de monetización</h2>${funnel(s.funnel)}<p class="muted">Ventas generadas atribuidas: <strong>${money(s.salesGenerated)}</strong>. No se contabilizan como ingresos propios.</p></article><article class="panel"><h2>Requieren atención</h2>${s.alerts.length?s.alerts.slice(0,5).map(a=>`<div class="alert"><strong>${esc(a.type)}</strong><br>${esc(a.message)}</div>`).join(''):'<p class="empty">Sin alertas pendientes.</p>'}</article></section><article class="panel" style="margin-top:18px"><h2>Rendimiento por producto</h2>${performanceTable(s.productPerformance)}</article>`) }
function funnel(f){const rows=[['Visitas',f.visits],['Vistas de producto',f.views],['Clics afiliados',f.clicks],['Conversiones',f.conversions],['Aprobadas',f.approved],['Pagadas',f.paid]];return `<div class="table-wrap"><table class="table"><tbody>${rows.map(([name,count],i)=>`<tr><td><strong>${name}</strong></td><td>${count}</td><td>${i?`${rows[i-1][1]?Math.round(count/rows[i-1][1]*100):0}% del paso anterior`:'Base del embudo'}</td></tr>`).join('')}</tbody></table></div>`}
function performanceTable(rows){return `<div class="table-wrap"><table class="table"><thead><tr><th>Producto</th><th>Vistas</th><th>Clics</th><th>CTR</th><th>Conversiones</th><th>Comisión</th><th>EPC</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.views}</td><td>${x.clicks}</td><td>${x.ctr}%</td><td>${x.conversions}</td><td>${money(x.commission)}</td><td>${money(x.epc)}</td></tr>`).join('')}</tbody></table></div>`}
const productSlug=p=>`${String(p.name||'oferta').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'oferta'}-${p.id}`;
function affiliateQuery(placement,sourceOverride){const params=new URLSearchParams(location.search),source=sourceOverride||params.get('utm_source')||params.get('source')||'store',medium=params.get('utm_medium')||params.get('medium')||'',campaign=params.get('utm_campaign')||params.get('campaign')||'',query=new URLSearchParams({sid:state.visitor,placement,source,consent:state.analyticsConsent==='granted'?'1':'0'});if(medium)query.set('medium',medium);if(campaign)query.set('campaign',campaign);return `?${query.toString()}`}
function visibleProducts(){const query=state.query.trim().toLocaleLowerCase('es'),products=(state.data.products||[]).filter(p=>{const haystack=[p.name,p.description,p.category?.name,p.merchant?.name].join(' ').toLocaleLowerCase('es');return(!query||haystack.includes(query))&&(state.category==='all'||p.categoryId===state.category)});return products.sort((a,b)=>{if(state.sort==='price-low')return Number(a.price?.amount??Infinity)-Number(b.price?.amount??Infinity);if(state.sort==='price-high')return Number(b.price?.amount??-1)-Number(a.price?.amount??-1);if(state.sort==='name')return a.name.localeCompare(b.name,'es');return Number(b.price?.previousAmount||0)-Number(a.price?.previousAmount||0)})}
function store(){const p=visibleProducts(),categories=(state.data.categories||[...new Map((state.data.products||[]).filter(x=>x.category?.id).map(x=>[x.category.id,x.category])).values()]);return `<main class="store-shell" id="main-content" tabindex="-1"><header class="store-header"><button class="store-brand" data-section="store" aria-label="Inicio de Ndivepa">Ndi<em>vepa</em></button><div class="store-nav"><a href="#recomendaciones">Explorar</a><a href="#como-funciona">Cómo funciona</a><a href="/guias.html">Guías</a><a href="/privacidad.html">Privacidad</a><button class="saved-button" data-action="show-favorites" aria-label="Ver favoritos">♡ <span>${state.favorites.size}</span></button>${state.auth?'<button class="btn secondary" data-section="dashboard">Panel afiliados</button>':'<button class="btn secondary" data-action="login">Acceso administrativo</button>'}</div></header><section class="hero"><div><span class="eyebrow">RECOMENDACIONES SELECCIONADAS</span><h1>Decide mejor.<br><i>Compra con confianza.</i></h1><p>Una selección directa de herramientas y productos útiles. Te mostramos qué recomendamos, para quién es y dónde comprarlo.</p><a class="hero-cta" href="#recomendaciones">Explorar recomendaciones <span>→</span></a></div><div class="hero-orbit" aria-hidden="true"><div class="orbit-card"><span>Selección</span><strong>100%</strong><small>afiliada y transparente</small></div><div class="orbit-dot one"></div><div class="orbit-dot two"></div></div></section><section class="trust-strip" aria-label="Principios de Ndivepa"><div><strong>Selección editorial</strong><span>Solo recomendaciones relevantes</span></div><div><strong>Compra segura</strong><span>Directamente con el proveedor</span></div><div><strong>Transparencia total</strong><span>Podemos recibir una comisión</span></div></section><section id="recomendaciones" class="recommendations"><div class="store-title"><div><span class="eyebrow">EXPLORA</span><h2>Encuentra tu próxima gran decisión</h2><p class="muted" aria-live="polite">${p.length} recomendación${p.length===1?'':'es'} disponible${p.length===1?'':'s'}.</p></div><label class="sort-control">Ordenar<select id="product-sort"><option value="featured" ${state.sort==='featured'?'selected':''}>Destacados</option><option value="price-low" ${state.sort==='price-low'?'selected':''}>Menor precio</option><option value="price-high" ${state.sort==='price-high'?'selected':''}>Mayor precio</option><option value="name" ${state.sort==='name'?'selected':''}>Nombre</option></select></label></div><div class="discovery-controls"><label class="search-box"><span aria-hidden="true">⌕</span><input id="product-search" type="search" value="${esc(state.query)}" placeholder="Buscar productos, temas o marcas" aria-label="Buscar recomendaciones" autocomplete="off"></label><div class="category-chips" role="group" aria-label="Filtrar por categoría"><button class="chip ${state.category==='all'?'active':''}" data-action="filter-category" data-category="all" aria-pressed="${state.category==='all'}">Todo</button>${categories.map(c=>`<button class="chip ${state.category===c.id?'active':''}" data-action="filter-category" data-category="${c.id}" aria-pressed="${state.category===c.id}">${esc(c.name)}</button>`).join('')}</div></div><section class="store-products" aria-label="Recomendaciones">${p.map(publicCard).join('')||'<div class="empty search-empty"><h3>No encontramos esa recomendación</h3><p>Prueba con otra búsqueda o elimina los filtros.</p><button class="btn secondary" data-action="clear-filters">Limpiar filtros</button></div>'}</section></section><section id="como-funciona" class="how-it-works"><div><span class="eyebrow">CÓMO FUNCIONA</span><h2>Recomendaciones honestas, compras en el lugar correcto.</h2></div><ol><li><span>01</span><div><strong>Explora con criterio</strong><p>Evaluamos el contexto de cada oferta y seleccionamos opciones que merecen atención.</p></div></li><li><span>02</span><div><strong>Elige con contexto</strong><p>Revisa el producto, el comercio y el estado del enlace antes de salir de Ndivepa.</p></div></li><li><span>03</span><div><strong>Compra con el proveedor</strong><p>La transacción se realiza fuera de Ndivepa, en el sitio oficial de cada comercio.</p></div></li></ol></section><footer class="store-footer"><div class="store-brand">Ndi<em>vepa</em></div><p>${esc(state.data.settings?.affiliateDisclosure||'')}</p><button class="text-button" data-action="manage-consent">Preferencias de privacidad</button><span>© ${new Date().getFullYear()} Ndivepa</span></footer></main>`}
function publicCard(p){const amount=p.price?.amount,old=p.price?.previousAmount,saved=state.favorites.has(p.id),discount=old&&amount&&old>amount?Math.round((1-amount/old)*100):null;return `<article class="product-card public-card" data-product="${p.id}"><div class="product-icon">${media(p.image,p.name)}${discount?`<b class="discount">-${discount}%</b>`:''}<button class="favorite ${saved?'saved':''}" data-action="toggle-favorite" data-id="${p.id}" aria-label="${saved?'Quitar de':'Guardar en'} favoritos" aria-pressed="${saved}">${saved?'♥':'♡'}</button></div><div class="product-info"><div class="card-meta"><span class="badge">${esc(p.category?.name||'Otro')}</span><span>${esc(p.merchant?.name||'Proveedor')}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="price-line"><span>${old?`<s>${money(old,p.price.currency)}</s>`:''}<strong>${money(amount,p.price?.currency)}</strong></span>${status(p.link?.health?.state||'warning')}</div><div class="card-actions"><a class="text-button" href="/producto/${productSlug(p)}">Ver ficha</a>${p.link?.id?`<a class="btn offer-button" href="/go/${p.link.id}${affiliateQuery('plc-home')}" target="_blank" rel="sponsored nofollow noopener noreferrer">Ver oferta <span>↗</span></a>`:'<span class="badge warn">Oferta no disponible</span>'}</div></div></article>`}
function productDetail(id){const p=(state.data.products||[]).find(x=>x.id===id);if(!p)return;const old=p.price?.previousAmount,amount=p.price?.amount;modal(`<header><div><span class="eyebrow">RECOMENDACIÓN NDIVEPA</span><h2>${esc(p.name)}</h2></div><button class="icon-btn" data-close aria-label="Cerrar detalle">Cerrar</button></header><div class="detail-product"><div class="detail-icon">${media(p.image,p.name)}</div><div><div class="card-meta"><span class="badge">${esc(p.category?.name||'Otro')}</span><span>${esc(p.merchant?.name||'Proveedor')}</span></div><p>${esc(p.description)}</p><div class="detail-price">${old?`<s>${money(old,p.price?.currency)}</s>`:''}<strong>${money(amount,p.price?.currency)}</strong></div><div class="detail-notes"><p><strong>Compra externa:</strong> finalizarás tu compra directamente en ${esc(p.merchant?.name||'el proveedor')}.</p><p><strong>Enlace revisado:</strong> ${esc(p.link?.validation?.messages?.[0]||'Revisión pendiente.')}</p><p><strong>Divulgación:</strong> ${esc(state.data.settings?.affiliateDisclosure||'')}</p></div>${p.link?.id?`<a class="btn offer-button detail-cta" href="/go/${p.link.id}${affiliateQuery('plc-featured','product-detail')}" target="_blank" rel="sponsored nofollow noopener noreferrer">Ir a la oferta de ${esc(p.merchant?.name||'proveedor')} <span>↗</span></a>`:''}</div></div>`)}
function products(){return layout(`${header('Productos afiliados','Cada producto conserva su comercio, programa, enlace y estado de validación.','<button class="btn" data-action="new-product">+ Agregar producto</button>')}<section class="catalog">${state.data.products.map(p=>`<article class="product-card"><div class="product-icon">${media(p.image,p.name)}</div><div class="product-info"><div class="panel-head"><h3>${esc(p.name)}</h3>${status(p.status)}</div><p>${esc(p.description)}</p><p class="muted">${esc(p.merchant?.name||'—')} · ${esc(p.program?.name||'—')}</p><div class="product-bottom"><strong>${money(p.price?.amount,p.price?.currency)}</strong>${status(p.link?.status||'missing')}</div><div class="actions" style="margin-top:12px"><button class="icon-btn" data-edit-product="${p.id}">Editar</button><button class="icon-btn" data-action="validate-link" data-id="${p.link?.id||''}">Validar enlace</button><button class="icon-btn danger" data-action="delete-product" data-id="${p.id}">Eliminar</button></div></div></article>`).join('')}</section>`) }
function editProduct(id){const product=state.data.products.find(item=>item.id===id),link=product&&state.data.links.find(item=>item.productId===id);if(!product)return;modal(`<header><h2>Editar producto afiliado</h2><button class="icon-btn" data-close>Cerrar</button></header><form id="edit-product-form"><div class="form-grid"><div class="field"><label>Nombre</label><input name="name" value="${esc(product.name)}" required></div><div class="field"><label>Tipo</label><input name="type" value="${esc(product.type||'other')}" required></div></div><div class="field"><label>Descripción propia</label><textarea name="description" required>${esc(product.description)}</textarea></div><div class="form-grid"><div class="field"><label>Categoría</label><select name="categoryId">${state.data.categories.map(item=>`<option value="${item.id}" ${item.id===product.categoryId?'selected':''}>${esc(item.name)}</option>`).join('')}</select></div><div class="field"><label>Comercio</label><select name="merchantId">${state.data.merchants.map(item=>`<option value="${item.id}" ${item.id===product.merchantId?'selected':''}>${esc(item.name)}</option>`).join('')}</select></div><div class="field"><label>Programa</label><select name="programId">${state.data.programs.map(item=>`<option value="${item.id}" ${item.id===product.programId?'selected':''}>${esc(item.name)}</option>`).join('')}</select></div><div class="field"><label>Publicación</label><select name="status"><option value="draft" ${product.status==='draft'?'selected':''}>Borrador</option><option value="published" ${product.status==='published'?'selected':''}>Publicado</option></select></div></div><div class="field"><label>Emoji o imagen interna</label><input name="image" value="${esc(product.image||'')}" placeholder="🔗 o /uploads/imagen.webp"></div><div class="field"><label>URL de afiliado</label><input name="affiliateUrl" type="url" value="${esc(link?.affiliateUrl||'')}" required></div><div class="form-grid"><div class="field"><label>Precio actual</label><input name="price" type="number" min="0" step="0.01" value="${product.price?.amount??''}"></div><div class="field"><label>Precio anterior</label><input name="previousAmount" type="number" min="0" step="0.01" value="${product.price?.previousAmount??''}"></div><div class="field"><label>Moneda</label><input name="currency" maxlength="3" value="${esc(product.price?.currency||'USD')}" required></div></div><div class="modal-footer"><span class="muted">Los cambios de enlace se validan antes de guardarse.</span><button class="btn">Guardar cambios</button></div></form>`);$('#edit-product-form').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit?.setAttribute('disabled','');try{const form=formValues(event.target),{affiliateUrl,price:currentPrice,previousAmount,currency,...changes}=form,validation=await api('/admin/links/validate',{method:'POST',body:JSON.stringify({affiliateUrl,merchantId:changes.merchantId,programId:changes.programId})});if(validation.status==='invalid')throw Error(validation.messages.join(' '));changes.price={...product.price,amount:currentPrice===''?null:Number(currentPrice),previousAmount:previousAmount===''?null:Number(previousAmount),currency:String(currency).toUpperCase(),updatedAt:currentPrice===''?null:new Date().toISOString()};const relationChanged=Boolean(link)&&(link.merchantId!==changes.merchantId||link.programId!==changes.programId);if(product.status==='published'&&relationChanged)await api(`/admin/products/${product.id}`,{method:'PATCH',body:JSON.stringify({status:'draft'})});if(link){await api(`/admin/links/${link.id}`,{method:'PATCH',body:JSON.stringify({affiliateUrl,merchantId:changes.merchantId,programId:changes.programId})});await api(`/admin/links/${link.id}/validate`,{method:'POST'})}await api(`/admin/products/${product.id}`,{method:'PATCH',body:JSON.stringify(changes)});closeModal();refresh('Producto y enlace actualizados y validados.')}catch(error){submit?.removeAttribute('disabled');toast(error.message)}}}
function resourcePage(kind,title,description,columns,adder){const rows=state.data[kind]||[];return layout(`${header(title,description,`<button class="btn" data-action="new-resource" data-resource="${kind}">+ ${adder}</button>`)}<article class="panel"><div class="table-wrap"><table class="table"><thead><tr>${columns.map(c=>`<th>${c[0]}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(c=>`<td>${c[1](row)}</td>`).join('')}<td><button class="icon-btn" data-action="delete-resource" data-resource="${kind}" data-id="${row.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></article>`) }
function merchants(){return resourcePage('merchants','Comercios','Catálogo de los proveedores donde se realiza la compra.',[['Comercio',x=>`<strong>${esc(x.name)}</strong>`],['Dominios',x=>esc((x.domains||[]).join(', '))],['Estado',x=>status(x.status||'active')]],'Agregar comercio')}
function programs(){const rows=state.data.programs||[];return layout(`${header('Programas de afiliación','Solo los programas aprobados y verificados pueden importar oportunidades.','<button class="btn" data-action="new-resource" data-resource="programs">+ Agregar programa</button>')}<article class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Programa</th><th>Tracking ID</th><th>Comisión</th><th>Aprobación</th><th>Descubrimiento</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.trackingId||'—')}</td><td>${x.estimatedCommission||0}%</td><td>${status(x.approvalStatus||'pending')}</td><td>${x.autoDiscovery?'<span class="badge good">Habilitado</span>':'<span class="badge warn">Manual</span>'}</td><td>${status(x.status)}</td><td><div class="actions"><button class="icon-btn" data-edit-program="${x.id}">Editar</button><button class="icon-btn danger" data-action="delete-resource" data-resource="programs" data-id="${x.id}">Eliminar</button></div></td></tr>`).join('')}</tbody></table></div></article>`)}
function campaigns(){return resourcePage('campaigns','Campañas','Agrupa productos y tráfico autorizado por campaña.',[['Campaña',x=>`<strong>${esc(x.name)}</strong><br><span class="muted">${esc(x.code||'')}</span>`],['Canal',x=>esc(x.channel||'—')],['Fechas',x=>`${esc(x.startsAt||'—')} → ${esc(x.endsAt||'—')}`],['Estado',x=>status(x.status)]],'Agregar campaña')}
function conversions(){return resourcePage('conversions','Conversiones','Compras, leads o reservas informados por red, importación o conciliación manual.',[['Conversión',x=>`<strong>${esc(x.networkConversionId||x.id)}</strong>`],['Producto',x=>esc(state.data.products.find(p=>p.id===x.productId)?.name||'—')],['Venta atribuida',x=>money(x.saleAmount,x.saleCurrency)],['Comisión',x=>money(x.commission,x.commissionCurrency)],['Estado',x=>status(x.status)]],'Registrar conversión')}
function commissions(){return resourcePage('commissions','Comisiones','Las comisiones pendientes no son ganancias definitivas.',[['Comisión',x=>`<strong>${x.id}</strong>`],['Producto',x=>esc(state.data.products.find(p=>p.id===x.productId)?.name||'—')],['Importe',x=>money(x.amount,x.currency)],['Estado',x=>status(x.status)],['Pago',x=>esc(x.paidAt||'Pendiente')]],'Registrar comisión')}
function links(){return layout(`${header('Enlaces y salud','Se valida estructura, comercio, programa y tracking. No se hacen peticiones externas ni se alteran parámetros.')}<article class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Producto</th><th>Destino afiliado</th><th>Validación</th><th>Salud</th><th>Última revisión</th><th></th></tr></thead><tbody>${state.data.links.map(l=>{const product=state.data.products.find(p=>p.id===l.productId);return `<tr><td><strong>${esc(product?.name||'—')}</strong></td><td class="muted">${esc(l.affiliateUrl)}</td><td>${status(l.status)}</td><td>${status(l.health?.state||'warning')}</td><td>${esc(l.validation?.checkedAt||'—')}</td><td><button class="icon-btn" data-action="validate-link" data-id="${l.id}">Validar</button></td></tr>`}).join('')}</tbody></table></div></article>`) }
function analyticsLegacy(){const s=state.data.summary;return layout(`${header('Analítica de afiliación','Atribución, fuentes y rendimiento para decidir qué ofertas potenciar.')}<section class="grid"><article class="panel"><h2>Fuentes de tráfico</h2>${s.sources.length?`<table class="table"><tbody>${s.sources.map(x=>`<tr><td><strong>${esc(x.source)}</strong></td><td>${x.count} eventos</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Sin eventos todavía.</p>'}</article><article class="panel"><h2>Indicadores</h2><p><strong>CTR afiliado:</strong> ${s.ctr}%</p><p><strong>Conversión:</strong> ${s.conversionRate}%</p><p><strong>EPC:</strong> ${money(s.epc)}</p><p class="muted">La retención y los usuarios activos exactos requieren telemetría propia o una integración autorizada con GA4.</p></article></section><article class="panel" style="margin-top:18px"><h2>Rendimiento por producto</h2>${performanceTable(s.productPerformance)}</article>`) }
const number=n=>new Intl.NumberFormat('es-PY').format(n||0),percentage=(now,before)=>before?Math.round((now-before)/before*100):now?'Nuevo':'0';
function analyticsSlice(){const days=state.analyticsDays==='all'?null:Number(state.analyticsDays),end=Date.now(),span=(days||36500)*86400000,start=days?end-span:0,previousStart=days?start-span:0;const inside=(date,from,to=end)=>{const value=new Date(date||0).getTime();return value>=from&&value<to};const events=state.data.events||[],conversions=state.data.conversions||[];return{days,start,events:events.filter(e=>inside(e.timestamp,start)),previousEvents:days?events.filter(e=>inside(e.timestamp,previousStart,start)):[],conversions:conversions.filter(c=>inside(c.date,start)),previousConversions:days?conversions.filter(c=>inside(c.date,previousStart,start)):[]}}
function countBy(items,getLabel){return Object.entries(items.reduce((all,item)=>{const label=getLabel(item)||'Sin atribución';all[label]=(all[label]||0)+1;return all},{})).map(([label,count])=>({label,count})).sort((a,b)=>b.count-a.count)}
function barRows(rows){const max=Math.max(...rows.map(row=>row.count),1);return rows.length?`<div class="bar-list">${rows.slice(0,6).map(row=>`<div class="bar-row"><span title="${esc(row.label)}">${esc(row.label)}</span><i><b style="width:${Math.max(6,row.count/max*100)}%"></b></i><strong>${number(row.count)}</strong></div>`).join('')}</div>`:'<p class="empty">Sin datos en este período.</p>'}
function dailyRows(events,conversions){const all={};for(const event of events){const day=(event.timestamp||'').slice(0,10);if(day)all[day]??={day,views:0,clicks:0,conversions:0},all[day][event.type==='affiliate_click'?'clicks':'views']++}for(const conversion of conversions){const day=(conversion.date||'').slice(0,10);if(day)all[day]??={day,views:0,clicks:0,conversions:0},all[day].conversions++}const rows=Object.values(all).sort((a,b)=>a.day.localeCompare(b.day)).slice(-10),max=Math.max(1,...rows.flatMap(row=>[row.views,row.clicks,row.conversions]));return rows.map(row=>({day:row.day,views:`<span class="trend-value views"><b style="width:${Math.max(5,row.views/max*100)}%"></b><i>${row.views}</i></span>`,clicks:`<span class="trend-value clicks"><b style="width:${Math.max(5,row.clicks/max*100)}%"></b><i>${row.clicks}</i></span>`,conversions:`<span class="trend-value conversions"><b style="width:${Math.max(5,row.conversions/max*100)}%"></b><i>${row.conversions}</i></span>`}))}
function analytics(){const data=analyticsSlice(),clicks=data.events.filter(e=>e.type==='affiliate_click'),views=data.events.filter(e=>e.type==='product_view'),previousClicks=data.previousEvents.filter(e=>e.type==='affiliate_click'),previousViews=data.previousEvents.filter(e=>e.type==='product_view'),productById=Object.fromEntries((state.data.products||[]).map(p=>[p.id,p]));const currentRate=views.length?Math.round(clicks.length/views.length*1000)/10:0,previousRate=previousViews.length?Math.round(previousClicks.length/previousViews.length*1000)/10:0;const merchant=countBy(clicks,e=>e.merchantId?state.data.merchants.find(m=>m.id===e.merchantId)?.name:productById[e.productId]?.merchant?.name);const program=countBy(clicks,e=>productById[e.productId]?.program?.name);const campaign=countBy(clicks,e=>e.campaignId?state.data.campaigns.find(c=>c.id===e.campaignId)?.name:'Sin campaña');const placement=countBy(clicks,e=>e.placementId||'Sin ubicación');const source=countBy(data.events,e=>e.source||'direct');const rows=dailyRows(data.events,data.conversions);const label=data.days?`Últimos ${data.days} días`:'Todo el historial';return layout(`${header('Analítica de afiliación',`${label}. Las ventas atribuidas y comisiones no se muestran como ingresos propios.`, '<button class="btn secondary" id="download-analytics">Descargar período CSV</button>')}<div class="analytics-toolbar"><label>Período<select id="analytics-range"><option value="7" ${state.analyticsDays==='7'?'selected':''}>Últimos 7 días</option><option value="30" ${state.analyticsDays==='30'?'selected':''}>Últimos 30 días</option><option value="90" ${state.analyticsDays==='90'?'selected':''}>Últimos 90 días</option><option value="all" ${state.analyticsDays==='all'?'selected':''}>Todo el historial</option></select></label><p class="muted">Comparación: período anterior equivalente.</p></div><section class="stats analytics-stats"><article class="stat"><span>Vistas</span><strong>${number(views.length)}</strong><small>${percentage(views.length,previousViews.length)}% vs. anterior</small></article><article class="stat"><span>Clics afiliados</span><strong>${number(clicks.length)}</strong><small>${percentage(clicks.length,previousClicks.length)}% vs. anterior</small></article><article class="stat"><span>CTR</span><strong>${currentRate}%</strong><small>${previousRate}% anterior</small></article><article class="stat"><span>Conversiones</span><strong>${number(data.conversions.length)}</strong><small>${percentage(data.conversions.length,data.previousConversions.length)}% vs. anterior</small></article></section><section class="grid analytics-grid"><article class="panel"><h2>Tráfico por fuente</h2>${barRows(source)}</article><article class="panel"><h2>Rendimiento diario</h2>${rows.length?`<div class="table-wrap"><table class="table compact"><thead><tr><th>Fecha</th><th>Vistas</th><th>Clics</th><th>Conversiones</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.day)}</td><td>${r.views}</td><td>${r.clicks}</td><td>${r.conversions}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Sin datos en este período.</p>'}</article></section><section class="analytics-breakdowns"><article class="panel"><h2>Comercios</h2>${barRows(merchant)}</article><article class="panel"><h2>Programas</h2>${barRows(program)}</article><article class="panel"><h2>Campañas</h2>${barRows(campaign)}</article><article class="panel"><h2>Ubicaciones</h2>${barRows(placement)}</article></section>`) }
function downloadAnalytics(){const data=analyticsSlice(),productById=Object.fromEntries((state.data.products||[]).map(p=>[p.id,p.name])),quote=value=>{let text=String(value??'');if(/^[\t\r ]*[=+\-@]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`},header=['fecha','tipo','producto','fuente','campaña','ubicación','click_id'],rows=data.events.map(e=>[e.timestamp,e.type,productById[e.productId]||e.productId,e.source,e.campaign,e.placementId,e.clickId]),csv=[header,...rows].map(row=>row.map(quote).join(',')).join('\r\n'),link=document.createElement('a'),url=URL.createObjectURL(new Blob([`\uFEFF${csv}\r\n`],{type:'text/csv;charset=utf-8'}));link.href=url;link.download=`ndivepa-analitica-${state.analyticsDays}-dias.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Informe del período descargado.')}
function alerts(){return layout(`${header('Alertas','Enlaces, programas, conversiones y patrones que requieren revisión.')}<section class="catalog">${state.data.alerts.map(a=>`<article class="panel"><div class="panel-head"><h2>${esc(a.type)}</h2>${status(a.severity)}</div><p>${esc(a.message)}</p><p class="muted">${esc(a.createdAt)}</p>${a.resolved?'':`<button class="icon-btn" data-action="resolve-alert" data-id="${a.id}">Marcar resuelta</button>`}</article>`).join('')||'<p class="empty">No hay alertas.</p>'}</section>`) }
function settings(){const maintenance=(state.data.audits||[]).find(item=>item.action==='local_maintenance');return layout(`${header('Seguridad y operación','Gestiona las credenciales locales y revisa las restricciones de integraciones externas.')}<section class="grid"><article class="panel"><h2>Cambiar contraseña</h2><form id="password-form"><div class="field"><label>Contraseña actual</label><input name="currentPassword" type="password" required></div><div class="field"><label>Nueva contraseña (12+ caracteres)</label><input name="newPassword" type="password" minlength="12" required></div><button class="btn">Actualizar contraseña</button></form></article><article class="panel"><h2>Operación y reglas activas</h2><p><strong>Último mantenimiento:</strong> ${maintenance?esc(new Date(maintenance.timestamp).toLocaleString('es-PY')):'Aún no ejecutado.'}</p><p>Administración protegida con sesión HttpOnly y rol de administrador.</p><p>Los enlaces bloquean protocolos inseguros, hosts internos e IPs directas.</p><p class="muted">Programa la revisión con <code>scripts/register-maintenance-task.ps1</code>. Los umbrales de enlace y precio se definen por variables de entorno.</p></article></section>`) }
function editProgram(id){
  const program=(state.data.programs||[]).find(item=>item.id===id);
  if(!program)return toast('El programa ya no existe.');
  const option=(value,label,current)=>'<option value="'+value+'" '+(value===current?'selected':'')+'>'+label+'</option>';
  const merchantOptions=(state.data.merchants||[]).map(item=>'<option value="'+esc(item.id)+'" '+(item.id===program.merchantId?'selected':'')+'>'+esc(item.name)+'</option>').join('');
  const networkOptions=(state.data.networks||[]).map(item=>'<option value="'+esc(item.id)+'" '+(item.id===program.networkId?'selected':'')+'>'+esc(item.name)+'</option>').join('');
  modal('<header><h2>Configurar programa afiliado</h2><button class="icon-btn" data-close>Cerrar</button></header><form id="edit-program-form"><div class="field"><label>Nombre</label><input name="name" value="'+esc(program.name)+'" required></div><div class="form-grid"><div class="field"><label>Comercio</label><select name="merchantId" required>'+merchantOptions+'</select></div><div class="field"><label>Red</label><select name="networkId" required>'+networkOptions+'</select></div><div class="field"><label>ID de afiliado</label><input name="affiliateId" value="'+esc(program.affiliateId||'')+'" required></div><div class="field"><label>Tracking ID</label><input name="trackingId" value="'+esc(program.trackingId||'')+'" required></div><div class="field"><label>Parámetro de tracking</label><input name="requiredTrackingKey" value="'+esc(program.requiredTrackingKey||'')+'" placeholder="tag" required></div><div class="field"><label>Comisión estimada</label><input name="estimatedCommission" type="number" min="0" step="0.01" value="'+esc(program.estimatedCommission??0)+'" required></div><div class="field"><label>Tipo de comisión</label><select name="commissionType">'+option('percentage','Porcentaje',program.commissionType)+option('flat','Importe fijo',program.commissionType)+option('tiered','Por tramos',program.commissionType)+'</select></div><div class="field"><label>Moneda</label><input name="commissionCurrency" maxlength="3" value="'+esc(program.commissionCurrency||'USD')+'"></div><div class="field"><label>Aprobación</label><select name="approvalStatus">'+option('pending','Pendiente',program.approvalStatus||'pending')+option('approved','Aprobada',program.approvalStatus)+option('revoked','Revocada',program.approvalStatus)+'</select></div><div class="field"><label>Credenciales verificadas el</label><input name="credentialsVerifiedAt" type="date" value="'+esc((program.credentialsVerifiedAt||'').slice(0,10))+'"></div><div class="field"><label>Descubrimiento</label><select name="autoDiscovery">'+option('false','Manual',String(Boolean(program.autoDiscovery)))+option('true','Habilitado',String(Boolean(program.autoDiscovery)))+'</select></div><div class="field"><label>Estado</label><select name="status">'+option('active','Activo',program.status)+option('paused','Pausado',program.status)+option('inactive','Inactivo',program.status)+'</select></div></div><p class="note">Marca “Aprobada”, registra la fecha de verificación y habilita descubrimiento solo después de comprobar tu cuenta en el panel oficial de la red.</p><div class="modal-footer"><span class="muted">Ndivepa verificará el tracking en cada enlace importado.</span><button class="btn">Guardar configuración</button></div></form>');
  $('#edit-program-form').onsubmit=async event=>{
    event.preventDefault();
    const submit=event.submitter;
    submit?.setAttribute('disabled','');
    try{
      const payload=formValues(event.target);
      payload.estimatedCommission=Number(payload.estimatedCommission);
      payload.autoDiscovery=payload.autoDiscovery==='true';
      if(!payload.credentialsVerifiedAt)delete payload.credentialsVerifiedAt;
      await api('/admin/programs/'+program.id,{method:'PATCH',body:JSON.stringify(payload)});
      closeModal();
      await load();
      render();
      toast('Programa afiliado actualizado.');
    }catch(error){
      submit?.removeAttribute('disabled');
      toast(error.message);
    }
  };
}
function discovery(){
  const items=state.opportunities||[],ready=state.opportunityPrograms||[],blocked=state.blockedPrograms||[],meta=state.opportunityMeta;
  const cards=items.map((item,index)=>{
    const news=(item.newsTitles||[]).map(title=>'<li>'+esc(title)+'</li>').join('');
    const label=item.productLikelihood>0?'Posible intención de producto':'Tendencia general';
    const action=item.alreadyCatalogued?'<span class="badge good">Ya está en catálogo</span>':'<button class="btn secondary" data-action="prepare-opportunity" data-index="'+index+'" '+(ready.length?'':'disabled')+'>Preparar producto</button>';
    return '<article class="panel trend-card"><div class="panel-head"><div><span class="eyebrow">'+esc(label)+'</span><h2>'+esc(item.query)+'</h2></div><span class="badge '+(item.productLikelihood>0?'good':'warn')+'">'+esc(item.approximateTraffic||'volumen no indicado')+'</span></div>'+(news?'<ul class="trend-context">'+news+'</ul>':'')+'<div class="panel-head"><span class="muted">'+esc(item.publishedAt?new Date(item.publishedAt).toLocaleString('es-PY'):'Sin fecha')+'</span>'+action+'</div></article>';
  }).join('');
  const blockedText=blocked.length?'<details class="panel"><summary>'+blocked.length+' programa(s) todavía no pueden importar</summary><ul>'+blocked.map(program=>'<li><strong>'+esc(program.name)+'</strong>: '+esc((program.reasons||[]).join(' '))+'</li>').join('')+'</ul></details>':'';
  const sourceLink=meta?'<p class="muted">'+esc(meta.attribution)+' · <a href="'+esc(meta.sourceUrl)+'" target="_blank" rel="noopener noreferrer">Abrir fuente oficial</a> · '+(meta.cached?'caché local':'actualizado ahora')+'</p>':'';
  return layout(header('Descubrimiento de oportunidades','Encuentra demanda reciente y conviértela en productos afiliados revisados.')+'<article class="panel discovery-intro"><h2>Google Trends + afiliación verificada</h2><p>Las tendencias son consultas con un aumento reciente, no una lista garantizada de productos. Ndivepa muestra el contexto y solo permite importar cuando el programa está aprobado, el tracking fue verificado y la URL afiliada exacta pasa todas las reglas.</p><div class="form-grid"><div class="field"><label>País (ISO)</label><input id="discovery-geo" maxlength="2" value="'+esc(state.discoveryGeo)+'" placeholder="PY"></div><div class="field discovery-submit"><label>Fuente</label><button class="btn" data-action="load-opportunities">Buscar tendencias ahora</button></div></div><p><strong>'+ready.length+'</strong> programa(s) listo(s) para importar.</p>'+sourceLink+'</article>'+blockedText+'<section class="trend-grid">'+(cards||'<div class="empty"><h2>Aún no hay resultados</h2><p>Configura un programa aprobado y pulsa “Buscar tendencias ahora”.</p></div>')+'</section>');
}
function opportunityForm(index){
  const opportunity=state.opportunities[index],programs=state.opportunityPrograms||[];
  if(!opportunity)return toast('La oportunidad ya no está disponible.');
  if(!programs.length)return toast('Primero configura un programa aprobado con tracking verificado.');
  const categories=state.data.categories||[];
  const programOptions=programs.map(program=>'<option value="'+esc(program.id)+'">'+esc(program.name)+' · '+esc(program.merchant?.name||'Comercio')+'</option>').join('');
  const categoryOptions='<option value="">Sin categoría</option>'+categories.map(category=>'<option value="'+esc(category.id)+'">'+esc(category.name)+'</option>').join('');
  const suggestedDescription='Producto relacionado con la tendencia “'+opportunity.query+'”. Completa aquí una descripción editorial propia antes de publicarlo.';
  modal('<header><div><span class="eyebrow">OPORTUNIDAD REVISADA</span><h2>Preparar producto afiliado</h2></div><button class="icon-btn" data-close>Cerrar</button></header><form id="opportunity-form"><div class="field"><label>Nombre del producto</label><input name="name" maxlength="200" value="'+esc(opportunity.query)+'" required></div><div class="field"><label>Descripción editorial</label><textarea name="description" minlength="20" required>'+esc(suggestedDescription)+'</textarea></div><div class="form-grid"><div class="field"><label>Programa afiliado aprobado</label><select name="programId" required>'+programOptions+'</select></div><div class="field"><label>Categoría</label><select name="categoryId">'+categoryOptions+'</select></div><div class="field"><label>Tipo</label><select name="type"><option value="physical">Producto físico</option><option value="digital">Producto digital</option><option value="service">Servicio</option><option value="course">Curso</option><option value="subscription">Suscripción</option><option value="other">Otro</option></select></div><div class="field"><label>Publicación</label><select name="publish"><option value="false">Guardar como borrador</option><option value="true">Publicar después de validar</option></select></div></div><div class="field"><label>URL oficial del producto</label><input name="productUrl" type="url" placeholder="https://comercio.com/producto" required></div><div class="field"><label>URL afiliada exacta con tu tracking</label><input name="affiliateUrl" type="url" placeholder="https://comercio.com/producto?tag=TU-ID" required></div><div class="form-grid"><div class="field"><label>Precio actual (opcional)</label><input name="price" type="number" min="0" step="0.01"></div><div class="field"><label>Precio anterior (opcional)</label><input name="previousPrice" type="number" min="0" step="0.01"></div><div class="field"><label>Moneda</label><input name="currency" value="USD" maxlength="3" required></div></div><p class="note">Ndivepa no modifica la URL afiliada. Debe ser el enlace emitido por la red y contener tu identificador real; de lo contrario, la importación se rechaza.</p><div class="modal-footer"><span class="muted">Demanda aproximada: '+esc(opportunity.approximateTraffic||'no indicada')+'</span><button class="btn">Validar y agregar</button></div></form>');
  $('#opportunity-form').onsubmit=async event=>{
    event.preventDefault();
    const submit=event.submitter;
    submit?.setAttribute('disabled','');
    try{
      const payload=formValues(event.target);
      payload.query=opportunity.query;
      payload.geo=state.discoveryGeo;
      payload.publish=payload.publish==='true';
      if(payload.price==='')delete payload.price;
      if(payload.previousPrice==='')delete payload.previousPrice;
      if(payload.categoryId==='')delete payload.categoryId;
      const result=await api('/v1/admin/affiliate-opportunities/import',{method:'POST',body:JSON.stringify(payload)});
      closeModal();
      state.section='products';
      await load();
      render();
      toast(result.published?'Producto publicado con enlace afiliado validado.':'Producto agregado como borrador con enlace afiliado validado.');
    }catch(error){
      submit?.removeAttribute('disabled');
      toast(error.message);
    }
  };
}
function consentBanner(){return `<aside class="consent-banner" role="dialog" aria-label="Preferencias de analítica"><div><strong>Tu privacidad, primero.</strong><p>Con tu permiso registramos vistas y clics internos para mejorar las recomendaciones. No instalamos píxeles externos.</p><a href="/privacidad.html">Ver privacidad</a></div><div class="consent-actions"><button class="icon-btn" data-consent="denied">Solo necesarias</button><button class="btn" data-consent="granted">Aceptar analítica</button></div></aside>`}
function enhanceAccessibility(root=document){root.querySelectorAll('.field').forEach((field,index)=>{const control=field.querySelector('input,select,textarea'),label=field.querySelector('label');if(control&&label){control.id||=`field-${index}-${Math.random().toString(36).slice(2,7)}`;label.htmlFor=control.id}});root.querySelectorAll('th').forEach(th=>th.setAttribute('scope','col'));root.querySelectorAll('button[data-action],button[data-section],button[data-close],button[data-consent],button[data-edit-product]').forEach(button=>button.type='button')}
function render(){viewObserver?.disconnect();if(!state.auth)state.section='store';const views={dashboard,products,discovery,merchants,programs,campaigns,conversions,commissions,links,analytics,alerts,settings,store};app.innerHTML=views[state.section]();if(state.section==='store'&&!state.analyticsConsent)app.insertAdjacentHTML('beforeend',consentBanner());enhanceAccessibility(app);bind();const passwordForm=$('#password-form');if(passwordForm)passwordForm.onsubmit=changePassword;if(state.section==='store')requestAnimationFrame(trackViews)}
function bind(){document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{state.section=b.dataset.section;render();$('#main-content')?.focus()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=actions);document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>editProduct(b.dataset.editProduct));document.querySelectorAll('[data-edit-program]').forEach(b=>b.onclick=()=>editProgram(b.dataset.editProgram));document.querySelectorAll('[data-consent]').forEach(b=>b.onclick=()=>{state.analyticsConsent=b.dataset.consent;storage.set('ndivepa-analytics-consent',state.analyticsConsent);render();if(state.analyticsConsent==='granted')trackViews()});const search=$('#product-search'),sort=$('#product-sort'),range=$('#analytics-range'),download=$('#download-analytics');if(search)search.oninput=e=>{state.query=e.target.value.slice(0,120);requestAnimationFrame(()=>{render();const next=$('#product-search');next?.focus();next?.setSelectionRange(state.query.length,state.query.length)})};if(sort)sort.onchange=e=>{state.sort=e.target.value;render()};if(range)range.onchange=e=>{state.analyticsDays=e.target.value;render()};if(download)download.onclick=downloadAnalytics}
async function actions(e){const b=e.currentTarget,a=b.dataset.action;try{if(a==='login')return login();if(a==='manage-consent'){state.analyticsConsent=null;storage.remove('ndivepa-analytics-consent');return render()}if(a==='toggle-favorite'){if(state.favorites.has(b.dataset.id))state.favorites.delete(b.dataset.id);else if(state.favorites.size<500)state.favorites.add(b.dataset.id);storage.set('ndivepa-favorites',JSON.stringify([...state.favorites]));return render()}if(a==='show-favorites'){const favorites=(state.data.products||[]).filter(p=>state.favorites.has(p.id)).map(p=>p.name).slice(0,8).join(' · ');return toast(favorites?`Guardadas: ${favorites}`:'Aún no guardaste recomendaciones.')}if(a==='filter-category'){state.category=b.dataset.category;return render()}if(a==='clear-filters'){state.query='';state.category='all';return render()}if(a==='open-product')return productDetail(b.dataset.id);if(a==='new-product')return productForm();if(a==='new-resource')return resourceForm(b.dataset.resource);if(a==='prepare-opportunity')return opportunityForm(Number(b.dataset.index));if(a==='validate-link'&&!b.dataset.id)return toast('El producto no tiene enlace.');b.disabled=true;b.setAttribute('aria-busy','true');if(a==='load-opportunities'){const geo=String($('#discovery-geo')?.value||state.discoveryGeo).trim().toUpperCase();if(!/^[A-Z]{2}$/.test(geo))throw Error('Usa un código de país de dos letras, por ejemplo PY.');const result=await api('/v1/admin/affiliate-opportunities?geo='+encodeURIComponent(geo)+'&limit=50&refresh=true');state.discoveryGeo=geo;state.opportunities=result.items||[];state.opportunityPrograms=result.eligiblePrograms||[];state.blockedPrograms=result.blockedPrograms||[];state.opportunityMeta=result;render();return toast('Tendencias actualizadas desde Google Trends.')}if(a==='logout'){await api('/auth/logout',{method:'POST'});state.auth=null;state.csrfToken=null;await load();render();return toast('Sesión cerrada.')}if(a==='resolve-alert'){await api(`/v1/admin/alerts/${b.dataset.id}/resolve`,{method:'POST',body:'{}'});return refresh('Alerta resuelta.')}if(a==='delete-product'){if(!confirm('¿Eliminar producto y su enlace?')){b.disabled=false;b.removeAttribute('aria-busy');return}await api(`/admin/products/${b.dataset.id}`,{method:'DELETE'});return refresh('Producto eliminado.')}if(a==='validate-link'){await api(`/admin/links/${b.dataset.id}/validate`,{method:'POST'});return refresh('Validación actualizada.')}if(a==='delete-resource'){if(!confirm('¿Eliminar este registro?')){b.disabled=false;b.removeAttribute('aria-busy');return}await api(`/admin/${b.dataset.resource}/${b.dataset.id}`,{method:'DELETE'});return refresh('Registro eliminado.')}}catch(err){b.disabled=false;b.removeAttribute('aria-busy');toast(err.message)}}
function modal(content){$('#modal')?.remove();const opener=document.activeElement;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal" role="dialog" aria-modal="true"><div class="modal-card">${content}</div></div>`);const dialog=$('#modal'),title=dialog.querySelector('h2');if(title){title.id=`modal-title-${Date.now()}`;dialog.setAttribute('aria-labelledby',title.id)}else dialog.setAttribute('aria-label','Ventana de Ndivepa');document.body.classList.add('modal-open');const focusables=()=>[...dialog.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')],close=()=>{document.removeEventListener('keydown',onKey);dialog.remove();document.body.classList.remove('modal-open');opener?.focus?.()},onKey=event=>{if(event.key==='Escape'){event.preventDefault();return close()}if(event.key==='Tab'){const items=focusables();if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};dialog.querySelector('[data-close]')?.addEventListener('click',close);dialog.addEventListener('mousedown',event=>{if(event.target===dialog)close()});document.addEventListener('keydown',onKey);enhanceAccessibility(dialog);setTimeout(()=>focusables()[0]?.focus(),0);const imageField=$('#edit-product-form [name="image"]');if(imageField){imageField.insertAdjacentHTML('afterend','<label class="upload-help">Cargar PNG, JPEG o WebP (máx. 700 KB)<input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"></label>');const picker=$('#edit-product-form [name="imageFile"]');picker.onchange=async event=>{const file=event.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>700000){event.target.value='';return toast('Usa PNG, JPEG o WebP de hasta 700 KB.')}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('No se pudo leer la imagen.'));reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)}),uploaded=await api('/admin/uploads',{method:'POST',body:JSON.stringify({data})});imageField.value=uploaded.url;toast('Imagen cargada de forma segura.')}catch(error){event.target.value='';toast(error.message)}}}}
function login(){modal(`<header><h2>Acceso administrativo</h2><button class="icon-btn" data-close>Cerrar</button></header><form id="login-form"><div class="field"><label>Correo</label><input name="email" type="email" autocomplete="username" placeholder="tu@correo.com" required></div><div class="field"><label>Contraseña</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn">Entrar</button></form>`);$('#login-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit?.setAttribute('disabled','');try{await api('/auth/login',{method:'POST',body:JSON.stringify(formValues(e.target))});await load();state.section='dashboard';closeModal();render()}catch(err){submit?.removeAttribute('disabled');toast(err.message)}}}
function productForm(){const d=state.data;modal(`<header><h2>Agregar producto afiliado</h2><button class="icon-btn" data-close>Cerrar</button></header><form id="product-form"><div class="form-grid"><div class="field"><label>Nombre</label><input name="name" placeholder="Notebook Lenovo LOQ 15" required></div><div class="field"><label>Tipo</label><select name="type"><option value="physical">Producto físico</option><option value="digital">Producto digital</option><option value="service">Servicio</option><option value="subscription">Suscripción</option><option value="course">Curso</option><option value="saas">SaaS</option><option value="reservation">Reserva</option><option value="other">Otro</option></select></div></div><div class="field"><label>Descripción corta propia</label><textarea name="description" required></textarea></div><div class="form-grid"><div class="field"><label>Categoría</label><select name="categoryId">${d.categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Comercio</label><select name="merchantId">${d.merchants.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Programa</label><select name="programId">${d.programs.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Campaña</label><select name="campaignId"><option value="">Sin campaña</option>${d.campaigns.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="field"><label>URL normal del producto</label><input name="productUrl" type="url" placeholder="https://..."></div><div class="field"><label>URL de afiliado</label><input name="affiliateUrl" type="url" placeholder="https://..." required></div><div class="form-grid"><div class="field"><label>Precio actual</label><input name="price" type="number" min="0" step="0.01"></div><div class="field"><label>Precio anterior</label><input name="previousPrice" type="number" min="0" step="0.01"></div><div class="field"><label>Moneda</label><input name="currency" value="USD"></div><div class="field"><label>Fuente precio</label><select name="priceSource"><option value="manual">Manual</option><option value="api">API/feed autorizado</option><option value="unknown">Desconocido</option></select></div></div><div class="field"><label>Publicación</label><select name="status"><option value="draft">Borrador</option><option value="published">Publicado</option></select></div><div class="modal-footer"><span class="muted">La URL se valida sin modificar sus parámetros.</span><button class="btn">Guardar y validar</button></div></form>`);$('#product-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit?.setAttribute('disabled','');try{const p=formValues(e.target);await api('/admin/products',{method:'POST',body:JSON.stringify(p)});closeModal();refresh('Producto creado y enlace validado.')}catch(err){submit?.removeAttribute('disabled');toast(err.message)}}}
function resourceForm(resource){const templates={merchants:{title:'Agregar comercio',fields:[['name','Nombre'],['domains','Dominios permitidos (separados por coma)']]},programs:{title:'Agregar programa',fields:[['name','Nombre'],['affiliateId','ID de afiliado'],['trackingId','Tracking ID'],['requiredTrackingKey','Parámetro de tracking'],['estimatedCommission','Comisión estimada (%)']]},campaigns:{title:'Agregar campaña',fields:[['name','Nombre'],['code','Código'],['channel','Canal']]},conversions:{title:'Registrar conversión',fields:[['networkConversionId','ID de red'],['clickId','Click ID (si existe)'],['saleAmount','Venta atribuida'],['commission','Comisión estimada']]},commissions:{title:'Registrar comisión',fields:[['amount','Importe'],['currency','Moneda']]}};const t=templates[resource];if(!t)return toast('Este recurso se administra mediante integración o API.');const related=resource==='programs'?`<div class="form-grid"><div class="field"><label>Comercio</label><select name="merchantId">${state.data.merchants.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Red de afiliación</label><select name="networkId">${state.data.networks.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Afiliación</label><select name="approvalStatus"><option value="pending">Pendiente</option><option value="approved">Aprobada</option><option value="revoked">Revocada</option></select></div><div class="field"><label>Credenciales verificadas el</label><input name="credentialsVerifiedAt" type="date"></div><div class="field"><label>Descubrimiento</label><select name="autoDiscovery"><option value="false">Manual</option><option value="true">Habilitado</option></select></div></div>`:resource==='conversions'||resource==='commissions'?`<div class="field"><label>Producto afiliado</label><select name="productId">${state.data.products.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div>`:'';modal(`<header><h2>${t.title}</h2><button class="icon-btn" data-close>Cerrar</button></header><form id="resource-form">${related}${t.fields.map(([n,l])=>`<div class="field"><label>${l}</label><input name="${n}" required></div>`).join('')}<div class="field"><label>Estado</label><select name="status"><option value="active">Activo</option><option value="pending">Pendiente</option><option value="approved">Aprobada</option><option value="confirmed">Confirmada</option><option value="paid">Pagada</option><option value="rejected">Rechazada</option><option value="reversed">Revertida</option></select></div><button class="btn">Guardar</button></form>`);$('#resource-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit?.setAttribute('disabled','');const p=formValues(e.target);if(p.domains)p.domains=p.domains.split(',').map(x=>x.trim()).filter(Boolean);if(p.estimatedCommission)p.estimatedCommission=Number(p.estimatedCommission);if(p.saleAmount)p.saleAmount=Number(p.saleAmount);if(p.commission)p.commission=Number(p.commission);const product=state.data.products.find(x=>x.id===p.productId);if(resource==='conversions'){p.type='purchase';p.date=new Date().toISOString();p.source='manual';p.saleCurrency='USD';p.commissionCurrency='USD';p.merchantId=product?.merchantId||null;p.networkId=product?.program?.networkId||null}if(resource==='commissions'){p.amount=Number(p.amount);p.currency=p.currency||'USD'}try{await api(`/admin/${resource}`,{method:'POST',body:JSON.stringify(p)});closeModal();refresh('Registro creado y auditado.')}catch(err){submit?.removeAttribute('disabled');toast(err.message)}}}
async function changePassword(event){event.preventDefault();const submit=event.submitter;submit?.setAttribute('disabled','');try{await api('/auth/password',{method:'POST',body:JSON.stringify(formValues(event.target))});event.target.reset();submit?.removeAttribute('disabled');toast('Contraseña actualizada correctamente.')}catch(error){submit?.removeAttribute('disabled');toast(error.message)}}
let viewObserver;async function trackViews(){if(state.analyticsConsent!=='granted')return;const cards=[...document.querySelectorAll('[data-product]')],track=card=>{const productId=card.dataset.product,key=`ndivepa-view-${productId}`;try{if(sessionStorage.getItem(key))return;sessionStorage.setItem(key,'1')}catch{}api('/events/view',{method:'POST',body:JSON.stringify({productId,sessionId:state.visitor,source:'direct',device:innerWidth<760?'mobile':'desktop',page:location.pathname,consent:true})}).catch(()=>{})};if(!('IntersectionObserver'in window)){cards.filter(card=>card.getBoundingClientRect().top<innerHeight).forEach(track);return}viewObserver?.disconnect();viewObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting&&entry.intersectionRatio>=.5){track(entry.target);viewObserver.unobserve(entry.target)}}),{threshold:.5});cards.forEach(card=>viewObserver.observe(card))}
async function refresh(message){await load();render();if(message)toast(message)}app.setAttribute('aria-busy','true');load().then(()=>{app.removeAttribute('aria-busy');render()}).catch(err=>{app.removeAttribute('aria-busy');app.innerHTML=`<main class="view" id="main-content"><div class="empty" role="alert"><h2>No se pudo iniciar Ndivepa</h2><p>${esc(err.message)}</p><button class="btn" id="retry-app">Reintentar</button></div></main>`;document.querySelector('#retry-app').onclick=()=>location.reload()});
